#[test]
fn duration_plan_rejects_wrong_account_at_claimed_root() {
    use rustaxa_evm::journal::DurationJournalEvent as E;
    let prior = [3_u8; 32];
    let output = [4_u8; 32];
    let address = [5_u8; 20];
    let expected = record(
        0.into(),
        ConcreteAccountBalance::new(BigUint::default()),
        None,
        0,
    );
    let wrong = record(
        1.into(),
        ConcreteAccountBalance::new(BigUint::default()),
        None,
        0,
    );
    let tagged = |bytes: &[u8]| {
        let mut row = vec![2];
        row.extend_from_slice(bytes);
        row
    };
    let row = |kind, owner, key: Vec<u8>, value: Vec<u8>| E {
        kind,
        address: owner,
        key,
        value,
    };
    let events = vec![
        row("plan_begin", [0; 20], prior.to_vec(), vec![2, 0, 0, 0, 0]),
        row(
            "plan_account",
            address,
            prior.to_vec(),
            tagged(&expected.physical_rlp),
        ),
        row("plan_end", [0; 20], prior.to_vec(), vec![2, 0, 0, 0, 0]),
        row("prepared_begin", [0; 20], prior.to_vec(), vec![]),
        row(
            "prepared_account",
            address,
            output.to_vec(),
            tagged(&wrong.physical_rlp),
        ),
        row(
            "prepared_plan_account",
            address,
            output.to_vec(),
            tagged(&wrong.physical_rlp),
        ),
        row("prepared_end", [0; 20], output.to_vec(), vec![]),
    ];
    assert!(duration_validate_plans(&events, prior, output, true).is_err());
    let mut duplicate = events.clone();
    duplicate.insert(5, duplicate[4].clone());
    assert!(duration_validate_plans(&duplicate, prior, output, true).is_err());
    let mut good = events.clone();
    good[4].value = tagged(&expected.physical_rlp);
    good[5].value = tagged(&expected.physical_rlp);
    good.push(row(
        "source_account",
        address,
        output.to_vec(),
        tagged(&expected.physical_rlp),
    ));
    duration_validate_plans(&good, prior, output, true).unwrap();
    let mut wrong_read = good.clone();
    wrong_read.last_mut().unwrap().value = tagged(&wrong.physical_rlp);
    assert!(duration_validate_plans(&wrong_read, prior, output, true).is_err());
    let mut wrong_root = good;
    wrong_root.last_mut().unwrap().key = prior.to_vec();
    assert!(duration_validate_plans(&wrong_root, prior, output, true).is_err());
}

#[test]
fn duration_plan_requires_identity_and_complete_stage() {
    use rustaxa_evm::journal::DurationJournalEvent as E;
    let root = [3_u8; 32];
    let row = |kind, key: Vec<u8>, value: Vec<u8>| E {
        kind,
        address: [0; 20],
        key,
        value,
    };
    let events = vec![
        row("plan_begin", root.to_vec(), vec![2, 0, 0, 0, 0]),
        row("plan_end", root.to_vec(), vec![2, 0, 0, 0, 0]),
        row("prepared_begin", root.to_vec(), vec![]),
        row("prepared_end", root.to_vec(), vec![]),
    ];
    duration_validate_plans(&events, root, root, true).unwrap();
    let mut wrong = events.clone();
    wrong[2].key[0] ^= 1;
    assert!(duration_validate_plans(&wrong, root, root, true).is_err());
    let mut missing = events.clone();
    missing.pop();
    assert!(duration_validate_plans(&missing, root, root, true).is_err());
    let mut duplicate = events;
    duplicate.insert(1, duplicate[0].clone());
    assert!(duration_validate_plans(&duplicate, root, root, true).is_err());
}

