#[test]
fn duration_settlement_facts_reject_nonempty_and_truncated() {
    let empty = hex::decode(format!(
        "01{}{:016x}01{}000000",
        "00".repeat(8),
        1_u64,
        "00".repeat(8)
    ))
    .unwrap();
    assert!(duration_settlement_deletable(&empty).unwrap());
    let mut nonce = vec![1];
    nonce.extend_from_slice(&1_u64.to_be_bytes());
    nonce.push(1);
    nonce.extend_from_slice(&1_u64.to_be_bytes());
    nonce.push(1);
    nonce.extend_from_slice(&0_u64.to_be_bytes());
    nonce.extend_from_slice(&[0, 0, 0]);
    assert!(!duration_settlement_deletable(&nonce).unwrap());
    assert!(duration_settlement_deletable(&empty[..empty.len() - 1]).is_err());
    assert!(duration_settlement_deletable(&[0]).is_err());
}

#[test]
fn duration_refund_frames_bind_opcode_and_child_merge() {
    let row = |kind: &str, key: String, value: String| serde_json::json!({"kind":kind,"key":key,"value":value});
    let id = |id: u64| format!("{id:016x}");
    let rust_key = format!("{:016x}{:016x}", 1_u64, 7_u64);
    let opcode_key = format!("{:016x}{:016x}{:02x}", 1_u64, 10_u64, 0x55_u8);
    let rust = vec![
        row("snapshot", id(0), String::new()),
        row("snapshot", id(7), String::new()),
        row(
            "frame_begin",
            rust_key.clone(),
            format!("{:016x}{:016x}{:016x}00", 0_u64, 0_u64, 0_u64),
        ),
        row(
            "refund_opcode",
            opcode_key.clone(),
            format!("{:016x}{:016x}01", 0_u64, 5_u64),
        ),
        row("checkpoint_commit", id(7), String::new()),
        row(
            "frame_end",
            rust_key,
            format!("{:016x}{:016x}{:016x}01", 0_u64, 5_u64, 5_u64),
        ),
        row("root_refund", id(0), id(5)),
        row("checkpoint_commit", id(0), String::new()),
    ];
    let go = vec![
        row("snapshot", id(1), String::new()),
        row(
            "frame_begin",
            id(8),
            format!("{:04x}{:016x}{:016x}00", 0_u16, 1_u64, 0_u64),
        ),
        row("snapshot", id(3), String::new()),
        row(
            "frame_begin",
            id(9),
            format!("{:04x}{:016x}{:016x}00", 1_u16, 3_u64, 0_u64),
        ),
        row(
            "refund_opcode",
            opcode_key,
            format!("{:016x}{:016x}01", 0_u64, 5_u64),
        ),
        row(
            "frame_end",
            id(9),
            format!("{:04x}{:016x}{:016x}01", 1_u16, 3_u64, 5_u64),
        ),
        row(
            "frame_end",
            id(8),
            format!("{:04x}{:016x}{:016x}01", 0_u16, 1_u64, 5_u64),
        ),
    ];
    duration_compare_refund_frames(&rust, &go).unwrap();
    let mut wrong = go.clone();
    wrong[4]["value"] = serde_json::json!(format!("{:016x}{:016x}01", 0_u64, 4_u64));
    assert!(duration_compare_refund_frames(&rust, &wrong).is_err());
    let mut wrong = rust;
    wrong[5]["key"] = serde_json::json!("00");
    assert!(duration_compare_refund_frames(&wrong, &go).is_err());
}

