struct DurationObservedFeeRead(FeeJournalRead);

impl rustaxa_types::concrete_state::execution::ConcreteExecutionRead for DurationObservedFeeRead {
    fn identity(&self) -> ConcreteStateIdentity {
        rustaxa_types::concrete_state::execution::ConcreteExecutionRead::identity(&self.0)
    }

    fn account(
        &self,
        address: [u8; 20],
    ) -> std::result::Result<ConcreteRead<ConcreteAccountRecord>, ConcreteReadError> {
        let result = rustaxa_types::concrete_state::execution::ConcreteExecutionRead::account(
            &self.0, address,
        );
        if let Ok(read) = &result {
            let mut value = Vec::new();
            match read {
                ConcreteRead::Absent => value.push(0),
                ConcreteRead::Tombstone => value.push(1),
                ConcreteRead::Present(record) => {
                    value.push(2);
                    value.extend_from_slice(&record.physical_rlp);
                }
            }
            rustaxa_evm::journal::duration_journal_plan_event(
                "source_account",
                address,
                &rustaxa_types::concrete_state::execution::ConcreteExecutionRead::identity(&self.0)
                    .state_root,
                &value,
            );
        }
        result
    }

    fn storage(
        &self,
        address: [u8; 20],
        key: ConcreteStorageKey,
    ) -> std::result::Result<ConcreteRead<Vec<u8>>, ConcreteReadError> {
        rustaxa_types::concrete_state::execution::ConcreteExecutionRead::storage(
            &self.0, address, key,
        )
    }

    fn code(
        &self,
        hash: [u8; 32],
    ) -> std::result::Result<ConcreteRead<Vec<u8>>, ConcreteReadError> {
        rustaxa_types::concrete_state::execution::ConcreteExecutionRead::code(&self.0, hash)
    }
}

#[test]
fn duration_helper_zero_nonce_requires_canonical_present_effect() {
    let author = [0x72; 20];
    rustaxa_evm::journal::duration_journal_arm(8192).unwrap();
    let mut journal = ExecutionJournal::new(FeeJournalRead {
        author,
        present: false,
        unavailable: false,
    });
    journal.set_nonce(author, FinalChainNonce::zero()).unwrap();
    let events = rustaxa_evm::journal::duration_journal_take().unwrap();
    let values = duration_journal_json(&events);
    duration_validate_helper_scopes(&values, true, true).unwrap();
    let nonce = values
        .iter()
        .position(|event| event["kind"] == "nonce")
        .unwrap();
    assert_eq!(values[nonce]["value"], "");
    let mut missing = values.clone();
    missing.remove(nonce);
    assert!(duration_validate_helper_scopes(&missing, true, true).is_err());
    let mut noncanonical = values;
    noncanonical[nonce]["value"] = serde_json::json!("00");
    assert!(duration_validate_helper_scopes(&noncanonical, true, true).is_err());
}

#[test]
fn duration_helper_scope_observes_actual_success_and_failure() {
    let author = [0x71; 20];
    rustaxa_evm::journal::duration_journal_arm(8192).unwrap();
    let mut journal = ExecutionJournal::new(FeeJournalRead {
        author,
        present: true,
        unavailable: false,
    });
    journal.add_balance(author, &BigUint::from(3_u64)).unwrap();
    journal
        .subtract_balance(author, &BigUint::from(1_u64))
        .unwrap();
    journal
        .set_nonce(author, FinalChainNonce::from_u64(8))
        .unwrap();
    assert!(
        journal
            .set_nonce(author, FinalChainNonce::from_u64(7))
            .is_err()
    );
    let events = rustaxa_evm::journal::duration_journal_take().unwrap();
    let scopes = events
        .iter()
        .filter(|event| matches!(event.kind, "helper_begin" | "helper_end"))
        .map(|event| {
            (
                event.kind,
                event.address,
                event.key.clone(),
                event.value.clone(),
            )
        })
        .collect::<Vec<_>>();
    assert_eq!(
        scopes,
        vec![
            ("helper_begin", author, vec![1], vec![2, 3]),
            ("helper_end", author, vec![1], vec![2, 3, 1]),
            ("helper_begin", author, vec![2], vec![2, 1]),
            ("helper_end", author, vec![2], vec![2, 1, 1]),
            ("helper_begin", author, vec![3], vec![2, 8]),
            ("helper_end", author, vec![3], vec![2, 8, 1]),
            ("helper_begin", author, vec![3], vec![2, 7]),
            ("helper_end", author, vec![3], vec![2, 7, 0])
        ]
    );
    assert_eq!(
        journal.account(author).unwrap().balance.value(),
        &BigInt::from(52)
    );
    assert_eq!(
        journal.account(author).unwrap().nonce,
        FinalChainNonce::from_u64(8)
    );
}

#[test]
fn duration_envelope_root_mutations_survive_nested_revert() {
    let author = [0x71; 20];
    rustaxa_evm::journal::duration_journal_arm(65_536).unwrap();
    let mut journal = ExecutionJournal::new(DurationObservedFeeRead(FeeJournalRead {
        author,
        present: true,
        unavailable: false,
    }));
    journal
        .subtract_balance(author, &BigUint::from(10_u64))
        .unwrap();
    journal
        .set_nonce(author, FinalChainNonce::from_u64(8))
        .unwrap();
    let checkpoint = journal.checkpoint();
    journal
        .subtract_balance(author, &BigUint::from(3_u64))
        .unwrap();
    journal.revert_checkpoint(checkpoint).unwrap();
    assert_eq!(
        journal.account(author).unwrap().balance.value(),
        &num_bigint::BigInt::from(40)
    );
    journal.add_balance(author, &BigUint::from(4_u64)).unwrap();
    assert_eq!(
        journal.account(author).unwrap().balance.value(),
        &num_bigint::BigInt::from(44)
    );
    journal.settle_transaction().unwrap();
    let events = rustaxa_evm::journal::duration_journal_take().unwrap();
    let event_charge = events
        .iter()
        .try_fold(0_usize, |total, event| {
            total
                .checked_add(256)?
                .checked_add(event.key.len())?
                .checked_add(event.value.len())
        })
        .unwrap();
    assert!(event_charge <= 65_536);
    eprintln!("envelope journal event charge: {event_charge} bytes");
    duration_validate_cached_reads(&events, false).unwrap();
    let without_source = events
        .iter()
        .filter(|event| event.kind != "source_account")
        .cloned()
        .collect::<Vec<_>>();
    assert!(duration_validate_cached_reads(&without_source, false).is_err());
    assert!(duration_validate_cached_reads(&events, true).is_err());
    let mut changed = events.clone();
    let restore = changed
        .iter_mut()
        .find(|event| event.kind == "restore_balance")
        .unwrap();
    restore.value = vec![0xff];
    assert!(duration_validate_cached_reads(&changed, false).is_err());
}

#[test]
fn duration_rejected_envelope_without_frame_replays() {
    use rustaxa_evm::contracts::{
        ExecutionGasPrice, ExecutionTransaction, ExecutionTransactionKind, ExecutionValue,
    };
    use rustaxa_evm::envelope::{EnvelopeAdmission, EnvelopeRules, IntrinsicGasSchedule, admit};
    use rustaxa_types::{FinalChainGas, FinalChainTransactionPosition};
    let author = [0x71; 20];
    rustaxa_evm::journal::duration_journal_arm(8192).unwrap();
    let mut journal = ExecutionJournal::new(DurationObservedFeeRead(FeeJournalRead {
        author,
        present: true,
        unavailable: false,
    }));
    let tx = ExecutionTransaction {
        position: FinalChainTransactionPosition::from(0_u32),
        hash: [0x11; 32],
        sender: author,
        receiver: Some([0xbb; 20]),
        nonce: FinalChainNonce::from_u64(7),
        gas_price: ExecutionGasPrice::new(BigUint::from(1_u8)),
        gas_limit: FinalChainGas::new(20_000),
        value: ExecutionValue::default(),
        input: Vec::new(),
        canonical_rlp: None,
        kind: ExecutionTransactionKind::Call,
    };
    let admission = admit(
        &mut journal,
        &tx,
        EnvelopeRules { cornus: false },
        IntrinsicGasSchedule::PINNED,
    )
    .unwrap();
    assert!(matches!(admission, EnvelopeAdmission::Rejected(_)));
    journal.account(author).unwrap();
    journal.settle_transaction().unwrap();
    let events = rustaxa_evm::journal::duration_journal_take().unwrap();
    assert!(!events.iter().any(|event| event.kind == "snapshot"));
    assert!(events.iter().any(|event| event.kind == "admission_terminal"
        && event.address == author
        && event.key == [1]));
    assert!(!events.iter().any(|event| event.kind == "transfer_decision"));
    assert!(events.iter().any(|event| event.kind == "balance"));
    duration_validate_cached_reads(&events, false).unwrap();
    let mut changed = events.clone();
    changed
        .iter_mut()
        .rev()
        .find(|event| event.kind == "read_account")
        .unwrap()
        .value = vec![0];
    assert!(duration_validate_cached_reads(&changed, false).is_err());
}

