fn duration_physical_digest(path: &Path) -> Result<[u8; 32]> {
    use k256::sha2::{Digest, Sha256};
    let options = rocksdb::Options::default();
    let columns = rocksdb::DB::list_cf(&options, path)?;
    let descriptors = columns
        .iter()
        .map(|name| rocksdb::ColumnFamilyDescriptor::new(name, rocksdb::Options::default()));
    let db = rocksdb::DB::open_cf_descriptors_read_only(&options, path, descriptors, false)?;
    let mut hash = Sha256::new();
    hash.update(b"duration-physical-rows-v1\0");
    for column in 1_u32..=5 {
        let name = column.to_string();
        let handle = db.cf_handle(&name).context("physical column")?;
        hash.update(column.to_be_bytes());
        for row in db.iterator_cf(handle, rocksdb::IteratorMode::Start) {
            let (key, value) = row?;
            hash.update((key.len() as u64).to_be_bytes());
            hash.update(&key);
            hash.update((value.len() as u64).to_be_bytes());
            hash.update(&value);
        }
    }
    Ok(hash.finalize().into())
}

