#[test]
#[ignore = "requires authenticated full restart owner"]
fn recovery_actual_full_prefix_rejects_boundary_mutations() -> Result<()> {
    let path = PathBuf::from(std::env::var("RUSTAXA_RECOVERY_RESTART_PATH")?);
    let hash = std::env::var("RUSTAXA_RECOVERY_RESTART_SHA256")?;
    let files = authenticated_files(&path, &hash, "public", true)?;
    let seed = fixed(&files.base["seed"]["root"]);
    let mut tape = Tape::new(
        files.ledger,
        files.effects,
        files.inputs,
        files.comparisons,
        files.last,
        seed,
    )?;
    let history = GoHistory::new(files.history, &files.base, 100_000_000, 8_589_934_592)?;
    let mut fold = DurationRestartGoFold::new(history, Some(5_893_460));
    let marker = loop {
        let record = tape.read_next()?.context("actual marker prefix")?;
        if record.period == 5_893_460 {
            let mut bad = TapeRecord {
                period: record.period,
                root: record.root,
                prior_root: record.prior_root,
                effects: record.effects.clone(),
                input: record.input.clone(),
                comparison: record.comparison.clone(),
            };
            bad.effects
                .as_object_mut()
                .context("actual marker effects")?
                .remove("state_owner_reopen");
            ensure!(
                duration_check_reopen_event(&bad, 5_893_460).is_err(),
                "missing marker accepted"
            );
            bad.effects = record.effects.clone();
            bad.root = [0; 32];
            ensure!(
                duration_check_reopen_event(&bad, 5_893_460).is_err(),
                "wrong marker root accepted"
            );
            fold.apply(&record, false)?;
            break record;
        }
        fold.apply(&record, false)?;
    };
    let pending = fold
        .pending
        .as_ref()
        .context("actual pending owner")?
        .clone();
    let id = fold
        .replay
        .last_wrapper
        .checked_add(1)
        .context("extra test owner")?;
    ensure!(
        fold.replay
            .wrappers
            .insert(id, SlashingWrapperCache::default())
            .is_none(),
        "extra owner occupied"
    );
    ensure!(
        pending
            .slots
            .clone()
            .into_pending(&marker, 5_893_460, &fold.replay)
            .is_err(),
        "extra live owner accepted"
    );
    fold.replay.wrappers.remove(&id);
    let removed_id = pending.slots.current;
    let removed = fold
        .replay
        .wrappers
        .remove(&removed_id)
        .context("actual current owner")?;
    ensure!(
        pending
            .slots
            .clone()
            .into_pending(&marker, 5_893_460, &fold.replay)
            .is_err(),
        "missing live owner accepted"
    );
    ensure!(
        fold.replay.wrappers.insert(removed_id, removed).is_none(),
        "current owner restored twice"
    );
    fold.replay.stack.push(id);
    ensure!(
        pending
            .slots
            .clone()
            .into_pending(&marker, 5_893_460, &fold.replay)
            .is_err(),
        "active operation accepted"
    );
    fold.replay.stack.pop();
    let record = tape.read_next()?.context("actual boundary record")?;
    let copy = || TapeRecord {
        period: record.period,
        root: record.root,
        prior_root: record.prior_root,
        effects: record.effects.clone(),
        input: record.input.clone(),
        comparison: record.comparison.clone(),
    };
    let actual = pending.clone().inspect_next(&record, &fold.replay)?;
    ensure!(actual.rows.len() == 12, "actual boundary proof size");
    let mut bad = copy();
    bad.prior_root = [0; 32];
    ensure!(
        pending.clone().inspect_next(&bad, &fold.replay).is_err(),
        "wrong boundary root accepted"
    );
    let mut bad = copy();
    bad.period += 1;
    ensure!(
        pending.clone().inspect_next(&bad, &fold.replay).is_err(),
        "wrong boundary period accepted"
    );
    for (index, key, value) in [
        (0, "wrapper_id", serde_json::json!(u64::MAX)),
        (0, "operation_id", serde_json::json!(u64::MAX)),
        (4, "wrapper_id", serde_json::json!(u64::MAX)),
        (4, "account_seed_view_known", serde_json::json!(true)),
        (5, "initial_cache_entries", serde_json::json!(1)),
        (5, "consumer_callbacks", serde_json::json!(1)),
    ] {
        let mut bad = copy();
        bad.effects["begin_accounts"][index][key] = value;
        ensure!(
            pending.clone().inspect_next(&bad, &fold.replay).is_err(),
            "changed boundary row accepted"
        );
    }
    let mut bad = copy();
    bad.effects["begin_accounts"]
        .as_array_mut()
        .context("actual begin")?
        .swap(0, 3);
    ensure!(
        pending.clone().inspect_next(&bad, &fold.replay).is_err(),
        "swapped source slots accepted"
    );
    let mut bad = copy();
    bad.effects["begin_accounts"]
        .as_array_mut()
        .context("actual begin")?
        .remove(0);
    ensure!(
        pending.clone().inspect_next(&bad, &fold.replay).is_err(),
        "missing boundary row accepted"
    );
    let mut bad = copy();
    let first = bad.effects["begin_accounts"][0].clone();
    bad.effects["begin_accounts"]
        .as_array_mut()
        .context("actual begin")?
        .insert(1, first);
    ensure!(
        pending.clone().inspect_next(&bad, &fold.replay).is_err(),
        "duplicate boundary row accepted"
    );
    let schedule =
        duration_go_seed_schedule(&record.effects, record.prior_root, record.root, false)?;
    ensure!(
        slashing_begin_setup_proof_with_reopen(record.period, &record.effects, &schedule, None)
            .is_err(),
        "boundary accepted without proof"
    );
    let mut moved = copy();
    let row = moved.effects["begin_accounts"]
        .as_array_mut()
        .context("actual begin")?
        .remove(0);
    moved.effects["end_accounts"]
        .as_array_mut()
        .context("actual end group")?
        .insert(0, row);
    ensure!(
        pending.clone().inspect_next(&moved, &fold.replay).is_err(),
        "moved boundary row accepted"
    );
    let mut proof = fold
        .apply(&record, false)?
        .context("actual boundary proof")?;
    let valid_schedule =
        duration_go_seed_schedule(&record.effects, record.prior_root, record.root, false)?;
    slashing_begin_setup_proof_with_reopen(
        record.period,
        &record.effects,
        &valid_schedule,
        Some(&proof),
    )?;
    proof.rows[0].1["scope"] = serde_json::json!("setup");
    ensure!(
        slashing_begin_setup_proof_with_reopen(
            record.period,
            &record.effects,
            &valid_schedule,
            Some(&proof)
        )
        .is_err(),
        "changed minted proof accepted"
    );
    ensure!(
        pending
            .inspect_next(&record, &SlashingCacheReplay::default())
            .is_err(),
        "unbound prior owner accepted"
    );
    let mut bad = copy();
    bad.effects["begin_accounts"][0]["scope"] = serde_json::json!("setup");
    let bad_schedule = duration_go_seed_schedule(&bad.effects, bad.prior_root, bad.root, false)?;
    ensure!(
        slashing_begin_setup_proof_with_reopen(bad.period, &bad.effects, &bad_schedule, None)
            .is_err(),
        "changed unproved row accepted"
    );
    Ok(())
}

#[test]
fn recovery_actual_allocator_rejects_duplicate_and_wrong_owner() -> Result<()> {
    let fixture: Value = serde_json::from_slice(include_bytes!("actual-go-recovery-prefix8.json"))?;
    let first = |side: &str| -> Result<Value> {
        let line = fixture[side]["effects"]
            .as_str()
            .context("actual prefix effects")?
            .lines()
            .next()
            .context("first actual effect")?;
        Ok(serde_json::from_str(line)?)
    };
    let left = first("baseline")?;
    let right = first("restart")?;
    let left = left["begin_accounts"]
        .as_array()
        .context("actual baseline begin")?;
    let right = right["begin_accounts"]
        .as_array()
        .context("actual restart begin")?;
    let mut relation = DurationRestartCorrespondence::default();
    relation.pair_rows(left, right)?;
    ensure!(
        relation.operations.is_empty() && relation.reverse_operations.is_empty(),
        "initial operations not retired"
    );
    let mut duplicate = right.clone();
    duplicate[2]["wrapper_id"] = duplicate[0]["wrapper_id"].clone();
    ensure!(
        DurationRestartCorrespondence::default()
            .pair_rows(left, &duplicate)
            .is_err(),
        "duplicate wrapper accepted"
    );
    let mut wrong = right.clone();
    wrong[1]["wrapper_id"] = serde_json::json!(u64::MAX);
    ensure!(
        DurationRestartCorrespondence::default()
            .pair_rows(left, &wrong)
            .is_err(),
        "wrong init owner accepted"
    );
    let mut moved = right.clone();
    moved.swap(0, 2);
    ensure!(
        DurationRestartCorrespondence::default()
            .pair_rows(left, &moved)
            .is_err(),
        "moved source slot accepted"
    );
    Ok(())
}
